// SPDX-License-Identifier: MIT
//! Drives `parse` through this module's OWN well-formedness inputs
//! (`wf_vectors.zig`, generated by `tools/gen_wf_vectors.py`). The inputs are
//! written for this repository; the verdict for each comes from libxml2
//! (through lxml) used as a black-box oracle, and for an accepted document the
//! oracle's view of it is a DUMP that `core_test.zig`'s `dump` reproduces.
//!
//! The W3C XML Conformance Test Suite is NOT in this repository (its files
//! carry no redistribution licence): `tools/xmlconf_fetch.sh` downloads it at
//! test time into a gitignored directory and `tools/xmlconf_run.zig` runs it.
//!
//! Every vector is run under the Options its `mode` names:
//!  - `.none`     default Options (the document has no DOCTYPE, so
//!                `doctype = .reject` cannot be the reason for a rejection);
//!  - `.ignore`   `Options{ .doctype = .ignore }`, the internal subset is a no-op;
//!  - `.entities` `Options{ .doctype = .internal_entities }`.
//! `ours` records a deliberate deviation from libxml2 and is asserted as such:
//! `"accept"` means this module takes what libxml2 refuses, an error name
//! means this module refuses (with exactly that error) what libxml2 takes,
//! `"infoset:" ++ DUMP` means it parses but builds that (different) infoset.

const std = @import("std");
const testing = std.testing;
const xml = @import("root.zig");
const wf = @import("wf_vectors.zig");
const core = @import("core_test.zig");

pub fn options(c: wf.Case) xml.Options {
    return .{ .doctype = switch (c.mode) {
        .none => .reject,
        .ignore => .ignore,
        .entities => .internal_entities,
    } };
}

test "wf corpus: canary (counts)" {
    // If this trips, tools/gen_wf_vectors.py changed: regenerate wf_vectors.zig
    // and update the numbers on purpose, not to make a failure go away.
    var rejected: usize = 0;
    var accepted: usize = 0;
    var deviations: usize = 0;
    for (wf.cases) |c| {
        if (c.ours != null) deviations += 1;
        if (c.lxml == null) rejected += 1 else accepted += 1;
    }
    try testing.expectEqual(@as(usize, 8), deviations);
    try testing.expectEqual(@as(usize, 245), rejected);
    try testing.expectEqual(@as(usize, 246), accepted);
    try testing.expectEqual(wf.cases.len, rejected + accepted);
}

test "wf corpus: every vector gets the recorded verdict" {
    const a = testing.allocator;
    var failures: usize = 0;
    for (wf.cases) |c| {
        const res = xml.parse(a, c.input, options(c));
        if (c.ours) |dev| {
            if (std.mem.startsWith(u8, dev, "infoset:")) {
                // Deviation: both accept, the infoset differs in the recorded way.
                std.debug.assert(c.lxml != null);
                var doc = res catch |e| {
                    if (e == error.OutOfMemory) return e;
                    std.debug.print("DEVIATION '{s}' ({s}): recorded an infoset but got {t}\n", .{ c.id, c.sections, e });
                    failures += 1;
                    continue;
                };
                defer doc.deinit();
                const got = try core.dumpDoc(a, &doc);
                defer a.free(got);
                if (!std.mem.eql(u8, dev["infoset:".len..], got) or std.mem.eql(u8, c.lxml.?, got)) {
                    std.debug.print("DEVIATION '{s}' ({s}): recorded {s}, libxml2 {s}, got {s}\n", .{ c.id, c.sections, dev, c.lxml.?, got });
                    failures += 1;
                }
            } else if (std.mem.eql(u8, dev, "accept")) {
                // Deviation: libxml2 refuses, this module accepts.
                std.debug.assert(c.lxml == null);
                if (res) |d| {
                    var doc = d;
                    doc.deinit();
                } else |e| {
                    std.debug.print("DEVIATION '{s}' ({s}): recorded 'accept' but got {t}\n", .{ c.id, c.sections, e });
                    failures += 1;
                }
            } else {
                // Deviation: libxml2 accepts, this module refuses with `dev`.
                std.debug.assert(c.lxml != null);
                if (res) |d| {
                    var doc = d;
                    doc.deinit();
                    std.debug.print("DEVIATION '{s}' ({s}): recorded {s} but it parsed\n", .{ c.id, c.sections, dev });
                    failures += 1;
                } else |e| {
                    if (!std.mem.eql(u8, dev, @errorName(e))) {
                        std.debug.print("DEVIATION '{s}' ({s}): recorded {s} but got {t}\n", .{ c.id, c.sections, dev, e });
                        failures += 1;
                    }
                }
            }
            continue;
        }
        if (c.lxml) |want| {
            var doc = res catch |e| {
                if (e == error.OutOfMemory) return e;
                std.debug.print("MISMATCH '{s}' ({s}, {s}): libxml2 accepts, got {t}\n", .{ c.id, c.sections, c.desc, e });
                failures += 1;
                continue;
            };
            defer doc.deinit();
            const got = try core.dumpDoc(a, &doc);
            defer a.free(got);
            if (!std.mem.eql(u8, want, got)) {
                std.debug.print("MISMATCH '{s}' ({s}, {s}): infoset differs from libxml2's\n  want {s}\n  got  {s}\n", .{ c.id, c.sections, c.desc, want, got });
                failures += 1;
            }
        } else {
            if (res) |d| {
                var doc = d;
                doc.deinit();
                std.debug.print("MISMATCH '{s}' ({s}, {s}): libxml2 refuses, but it parsed\n", .{ c.id, c.sections, c.desc });
                failures += 1;
            } else |e| {
                if (e == error.OutOfMemory) return e;
                // The default policy must not be the reason for a DOCTYPE-free rejection.
                if (e == error.DoctypeForbidden) {
                    std.debug.print("MISMATCH '{s}': rejected by the doctype policy, not by its defect\n", .{c.id});
                    failures += 1;
                }
            }
        }
    }
    try testing.expectEqual(@as(usize, 0), failures);
}

test "wf corpus: a DOCTYPE-bearing vector is refused under the default policy" {
    const a = testing.allocator;
    var seen: usize = 0;
    for (wf.cases) |c| {
        if (c.mode == .none or c.lxml == null) continue;
        if (std.mem.indexOf(u8, c.input, "<!DOCTYPE") == null) continue;
        try testing.expectError(error.DoctypeForbidden, xml.parse(a, c.input, .{}));
        seen += 1;
    }
    try testing.expect(seen > 40);
}

test "wf corpus: a no-op DOCTYPE vector also parses under .internal_entities" {
    const a = testing.allocator;
    for (wf.cases) |c| {
        if (c.mode != .ignore or c.lxml == null or c.ours != null) continue;
        var doc = xml.parse(a, c.input, .{ .doctype = .internal_entities }) catch |e| {
            std.debug.print("'{s}': {t}\n", .{ c.id, e });
            return e;
        };
        doc.deinit();
    }
}
